// Bloodright Jutsu Reference Library capture batches (push/*_bloodright_reference_capture_batch_*),
// generated by scripts/bloodright_reference.py manifests. Socket-free: each parses under Forge's own
// parser, plans zero items, carries at most 40 jutsu.get reads plus bloodline.get reads, all
// persist:"full", and runs against an in-process fake game with no procedure other than those reads.

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync } from "node:fs";
import { parseManifest, planOrder } from "../src/runner/manifest.mjs";
import { FakeGame } from "./fakegame.mjs";
import { MemoryStorage } from "./shim.mjs";
import { composeForTest } from "./compose.mjs";

const PUSH = new URL("../../push/", import.meta.url);
const BATCHES = readdirSync(PUSH).filter((n) => /^\d+_bloodright_reference_capture_batch_\d+\.json$/.test(n)).sort();
const MAX_JUTSU = 40;

test("the Bloodright reference capture batches are present", () => {
  assert.ok(BATCHES.length > 0);
});

for (const name of BATCHES) {
  const raw = () => JSON.parse(readFileSync(new URL(name, PUSH), "utf8"));

  test(`${name} is a capture-only job of full point reads within the jutsu cap`, () => {
    const body = raw();
    const m = parseManifest(JSON.stringify(body));
    assert.equal(planOrder(m).length, 0);
    assert.equal(m.fullCaptures, body.capture.before.length);
    assert.deepEqual(body.capture.after, []);
    for (const c of body.capture.before) {
      assert.ok(c.proc === "jutsu.get" || c.proc === "bloodline.get");
      assert.deepEqual(Object.keys(c.input), ["id"]);
    }
    assert.ok(body.capture.before.filter((c) => c.proc === "jutsu.get").length <= MAX_JUTSU);
  });

  test(`${name} runs read-only against a fake game`, async () => {
    const game = new FakeGame();
    const storage = new MemoryStorage();
    for (const c of raw().capture.before) {
      game.seed(c.proc === "jutsu.get" ? "jutsu" : "bloodline", { id: c.input.id, name: c.input.id, image: `https://utfs.io/f/${c.input.id}` });
    }
    const d = composeForTest({ game, storage });
    d.runner.plan(raw(), { jobId: "b", manifestPath: `push/${name}` });
    const s = await d.runner.run("b");
    assert.equal(s.state, "DONE");
    assert.equal(s.outcome, "success");
    assert.ok(game.calls.every((c) => c.path === "jutsu.get" || c.path === "bloodline.get"));
  });
}

test("the batches read every jutsu at most once", () => {
  const ids = BATCHES.flatMap((n) => JSON.parse(readFileSync(new URL(n, PUSH), "utf8")).capture.before.map((c) => c.input.id));
  assert.equal(new Set(ids).size, ids.length);
});
